<template><div class="app-container">
 <el-form :inline="true"><el-form-item label="课题"><el-select v-model="topicId" filterable @change="reload" style="width:360px"><el-option v-for="t in topics" :key="t.topicId" :label="t.topicName" :value="t.topicId"/></el-select></el-form-item></el-form>
 <el-row :gutter="12" class="mb8" v-if="overview"><el-col :span="6"><el-card>总资金<br><b>{{money(overview.totalAmount)}}</b></el-card></el-col><el-col :span="6"><el-card>已到位<br><b>{{money(overview.arrivedAmount)}}</b></el-card></el-col><el-col :span="6"><el-card>已使用<br><b>{{money(overview.usedAmount)}}</b></el-card></el-col><el-col :span="6"><el-card>待拨<br><b>{{money(overview.pendingAllocationAmount)}}</b></el-card></el-col></el-row>
 <el-button class="mb8" type="primary" plain size="mini" icon="el-icon-plus" @click="openPlan()" v-hasPermi="['fund:allocation:add']" :disabled="!topicId">新增拨付计划</el-button>
 <el-table :data="plans" v-loading="loading"><el-table-column label="拨付名称" prop="allocationName" min-width="180"/><el-table-column label="拨付单位" prop="allocationDeptName"/><el-table-column label="接收单位" prop="receiveDeptName"/><el-table-column label="计划金额" width="130"><template slot-scope="s">{{money(s.row.planAmount)}}</template></el-table-column><el-table-column label="责任人" prop="responsibleUserName" width="110"/><el-table-column label="状态" width="90"><template slot-scope="s"><el-tag :type="s.row.status==='1'?'success':'warning'">{{s.row.status==='1'?'已结束':'执行中'}}</el-tag></template></el-table-column><el-table-column label="操作" width="310"><template slot-scope="s"><el-button type="text" @click="openRecords(s.row)">拨付记录</el-button><el-button type="text" v-if="s.row.status==='0'" @click="openAssign(s.row)" v-hasPermi="['fund:allocation:assign']">责任人</el-button><el-button type="text" v-if="s.row.status==='0'" @click="openPlan(s.row)" v-hasPermi="['fund:allocation:edit']">编辑</el-button><el-button type="text" v-if="s.row.status==='0'" @click="finishPlan(s.row)" v-hasPermi="['fund:allocation:finish']">结束</el-button></template></el-table-column></el-table>
 <pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="loadPlans"/>
 <el-dialog :title="planForm.planId?'编辑拨付计划':'新增拨付计划'" :visible.sync="planOpen" width="650px"><el-form ref="planForm" :model="planForm" :rules="planRules" label-width="100px"><el-form-item label="拨付名称" prop="allocationName"><el-input v-model="planForm.allocationName"/></el-form-item><el-row :gutter="12"><el-col :span="12"><el-form-item label="拨付单位" prop="allocationDeptId"><el-select v-model="planForm.allocationDeptId" filterable style="width:100%"><el-option v-for="d in depts" :key="d.deptId" :label="d.deptName" :value="d.deptId"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="接收单位" prop="receiveDeptId"><el-select v-model="planForm.receiveDeptId" filterable style="width:100%"><el-option v-for="d in depts" :key="d.deptId" :label="d.deptName" :value="d.deptId"/></el-select></el-form-item></el-col></el-row><el-form-item label="拨付金额" prop="planAmount"><el-input-number v-model="planForm.planAmount" :precision="2" :min="0.01" :step="10000" style="width:100%"/></el-form-item><el-form-item label="拨付时间"><el-date-picker v-model="planForm.planTime" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="资金说明"><el-input type="textarea" v-model="planForm.fundDesc"/></el-form-item></el-form><div slot="footer"><el-button @click="planOpen=false">取消</el-button><el-button type="primary" @click="savePlan">确定</el-button></div></el-dialog>
 <el-dialog title="指定责任人" :visible.sync="assignOpen" width="460px"><el-select v-model="assignUserId" clearable filterable style="width:100%"><el-option v-for="u in assignUsers" :key="u.userId" :label="u.nickName||u.userName" :value="u.userId"/></el-select><div slot="footer"><el-button @click="assignOpen=false">取消</el-button><el-button type="primary" @click="saveAssign">确定</el-button></div></el-dialog>
 <el-dialog :title="recordPlan.allocationName+' - 拨付记录'" :visible.sync="recordsOpen" width="900px"><el-button v-if="recordPlan.status==='0'" type="primary" plain size="mini" @click="openRecord()" v-hasPermi="['fund:allocation:submit']">提交拨付</el-button><el-table :data="records"><el-table-column label="名称" prop="allocationName"/><el-table-column label="金额" width="120"><template slot-scope="s">{{money(s.row.amount)}}</template></el-table-column><el-table-column label="提交人" prop="submitUserName"/><el-table-column label="时间" prop="allocationTime" width="165"/><el-table-column label="操作" width="120"><template slot-scope="s"><el-button v-if="recordPlan.status==='0'" type="text" @click="openRecord(s.row)">编辑</el-button><el-button v-if="recordPlan.status==='0'" type="text" @click="deleteRecord(s.row)">删除</el-button></template></el-table-column></el-table></el-dialog>
 <el-dialog title="拨付记录" :visible.sync="recordOpen" width="600px"><el-form ref="recordForm" :model="recordForm" :rules="recordRules" label-width="100px"><el-form-item label="拨付名称" prop="allocationName"><el-input v-model="recordForm.allocationName"/></el-form-item><el-form-item label="拨付金额" prop="amount"><el-input-number v-model="recordForm.amount" :min="0.01" :precision="2" style="width:100%"/></el-form-item><el-form-item label="拨付时间" prop="allocationTime"><el-date-picker v-model="recordForm.allocationTime" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="资金说明"><el-input type="textarea" v-model="recordForm.fundDesc"/></el-form-item><el-form-item label="拨付凭证"><file-upload v-model="recordForm.voucherUrls" :limit="5" :fileType="['pdf','doc','docx','xls','xlsx','jpg','jpeg','png']"/></el-form-item></el-form><div slot="footer"><el-button @click="recordOpen=false">取消</el-button><el-button type="primary" @click="saveRecord">确定</el-button></div></el-dialog>
</div></template>
<script>
import {groupOptions} from '@/api/research/group';import {getOverview} from '@/api/fund/budget';import {listFundDepts,listFundUsers} from '@/api/fund/org';import {listAllocationPlans,getAllocationPlan,addAllocationPlan,updateAllocationPlan,assignAllocation,listAllocationRecords,addAllocationRecord,updateAllocationRecord,delAllocationRecord,allocationFinishCheck,finishAllocation} from '@/api/fund/allocation';
export default{name:'FundAllocation',data(){return{topics:[],topicId:null,overview:null,depts:[],plans:[],loading:false,total:0,query:{pageNum:1,pageSize:10},planOpen:false,planForm:{},assignOpen:false,assignPlan:null,assignUsers:[],assignUserId:null,recordsOpen:false,recordPlan:{},records:[],recordOpen:false,recordForm:{},planRules:{allocationName:[{required:true,message:'请输入拨付名称'}],allocationDeptId:[{required:true,message:'请选择拨付单位'}],receiveDeptId:[{required:true,message:'请选择接收单位'}],planAmount:[{required:true,message:'请输入金额'}]},recordRules:{allocationName:[{required:true,message:'请输入名称'}],amount:[{required:true,message:'请输入金额'}],allocationTime:[{required:true,message:'请选择时间'}]}}},created(){listFundDepts().then(r=>this.depts=r.data||[]);groupOptions().then(r=>{this.topics=(r.data||[]).map(g=>({topicId:g.groupId,topicName:g.groupName}));if(this.topics.length){this.topicId=this.topics[0].topicId;this.reload()}})},methods:{money(v){return Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2})},reload(){this.loadPlans();getOverview(this.topicId).then(r=>this.overview=r.data).catch(()=>this.overview=null)},loadPlans(){if(!this.topicId)return;this.loading=true;listAllocationPlans(Object.assign({},this.query,{topicId:this.topicId})).then(r=>{this.plans=r.rows;this.total=r.total;this.loading=false})},openPlan(row){this.planForm=row?Object.assign({},row):{topicId:this.topicId,allocationName:'',allocationDeptId:null,receiveDeptId:null,planAmount:0,planTime:null,fundDesc:''};this.planOpen=true},savePlan(){this.$refs.planForm.validate(ok=>{if(!ok)return;(this.planForm.planId?updateAllocationPlan:addAllocationPlan)(this.planForm).then(()=>{this.$modal.msgSuccess('保存成功');this.planOpen=false;this.reload()})})},openAssign(row){this.assignPlan=row;this.assignUserId=row.responsibleUserId;listFundUsers(row.allocationDeptId).then(r=>{this.assignUsers=r.data||[];this.assignOpen=true})},saveAssign(){assignAllocation(this.assignPlan.planId,this.assignUserId).then(()=>{this.$modal.msgSuccess('责任人已更新');this.assignOpen=false;this.loadPlans()})},openRecords(row){this.recordPlan=row;listAllocationRecords(row.planId).then(r=>{this.records=r.data||[];this.recordsOpen=true})},openRecord(row){this.recordForm=row?Object.assign({},row):{planId:this.recordPlan.planId,allocationName:'',amount:0,allocationTime:null,fundDesc:'',voucherUrls:''};this.recordOpen=true},saveRecord(){this.$refs.recordForm.validate(ok=>{if(!ok)return;(this.recordForm.recordId?updateAllocationRecord:addAllocationRecord)(this.recordForm).then(()=>{this.$modal.msgSuccess('保存成功');this.recordOpen=false;this.openRecords(this.recordPlan);this.reload()})})},deleteRecord(row){this.$modal.confirm('确认删除该拨付记录？').then(()=>delAllocationRecord(row.recordId)).then(()=>{this.openRecords(this.recordPlan);this.reload()})},finishPlan(row){allocationFinishCheck(row.planId).then(r=>{const c=r.data;const msg=!c.needConfirm?'实际金额与计划一致，确认结束？':(c.differenceAmount<0?'还有余额 '+Math.abs(c.differenceAmount)+' 元未拨付，确认结束？':'实际拨付超出计划 '+Math.abs(c.differenceAmount)+' 元，确认结束？');this.$modal.confirm(msg).then(()=>finishAllocation(row.planId,c.needConfirm)).then(()=>{this.$modal.msgSuccess('计划已结束');this.reload()})})}}}
</script>
